/*
 * The favicon: the Flöra bud mark (the Ö of the wordmark) on a disc. Two colourways, chosen under
 * Settings & brand. The SVG is drawn here; the PNGs (for Safari, and the iPhone home screen) are
 * the same drawing rendered once and kept inline, so the icon routes never touch the file system.
 */
import { BUD_MARK } from "./bud-mark";

const [RING, DOT_LEFT, DOT_RIGHT] = BUD_MARK.paths;

export const FAVICON_STYLES = ["black", "white"] as const;
export type FaviconStyle = (typeof FAVICON_STYLES)[number];
export const FAVICON_LABEL: Record<FaviconStyle, string> = { black: "Black disc, white mark", white: "White disc, black mark" };
export const parseFaviconStyle = (v: unknown): FaviconStyle => (v === "white" ? "white" : "black");


export function faviconSvg(style: FaviconStyle, size?: number): string {
  const disc = style === "white" ? "#fff" : "#000";
  const mark = style === "white" ? "#000" : "#fff";
  const dims = size ? ` width="${size}" height="${size}"` : "";
  return `<svg xmlns="http://www.w3.org/2000/svg"${dims} viewBox="0 0 40 40"><circle cx="20" cy="20" r="20" fill="${disc}"/><g fill="${mark}" transform="translate(6 5.2) scale(0.78)"><path d="${RING}"/><path d="${DOT_LEFT}"/><path d="${DOT_RIGHT}"/></g></svg>`;
}

/** 32×32 PNG of each colourway, transparent outside the disc. */
export const FAVICON_PNG: Record<FaviconStyle, string> = {
  black: "",
  white: "",
};

/** 180×180 PNG of each colourway on a white tile, for the iPhone home screen (iOS rounds the corners). */
export const APPLE_ICON_PNG: Record<FaviconStyle, string> = {
  black: "",
  white: "",
};

/** 192 and 512 px PNGs on a white tile, for Android home screens and the web app manifest. */
export const PWA_ICON_PNG: Record<FaviconStyle, Record<192 | 512, string>> = {
  black: { 192: "", 512: "" },
  white: { 192: "", 512: "" },
};
